    public function scopeFilterListing(Builder $query, \Illuminate\Http\Request $request)
    {
        // Search filter
        if ($request->filled('search')) {
            $search = $request->search;
            $query->where(function($q) use ($search) {
                $q->where('booking_number', 'like', '%' . $search . '%')
                    ->orWhere('employee_name', 'like', '%' . $search . '%')
                    ->orWhereHas('bookingContainers', function($container) use($search){
                        $container->where('container_no', 'like', '%' . $search . '%');
                    })
                    ->orWhereHas('factory', function($factory) use($search){
                        $factory->where('name', 'like', '%' . $search . '%');
                    })
                    ->orWhereHas('invoice', function($invoice) use($search){
                        $invoice->where('invoice_number', 'like', '%' . $search . '%');
                    });
            });
        }

        // Date range filter
        if ($request->filled('date_from') || $request->filled('date_to')) {
            $query->filterDateRange($request->input('date_from'), $request->input('date_to'));
        }

        // Company filter
        if ($request->filled("company")) {
            $query->filterCompany($request->input('company'));
        }

        // Tax status filter
        if ($request->filled("tax_status")) {
            $query->filterTaxStatus($request->input('tax_status'));
        }

        // Invoice status filter
        if ($request->filled("invoice_status")) {
            if ($request->invoice_status == '1') {
                $query->whereHas('invoice');
            } else {
                $query->whereDoesntHave('invoice');
            }
        }

        return $query;
    }

public function scopeFilterStage(Builder $query, ?string $stage)
{
    $query->when($stage && $stage !== 'all', function (Builder $query) use ($stage) {
        switch ($stage) {
            case 'assigned':
            case 'specification':
            case '0':
                $query->whereHas('bookingContainers', function ($q) {
                    $q->where(function ($sub) {
                        $sub->where('status', 0)
                            ->orWhere(function ($q2) {
                                $q2->where('status', 1)->where('superagent_specification_approved', 0);
                            });
                    });
                });
                break;

            case 'waiting':
            case 'waiting_loading':
                $query->whereHas('bookingContainers', function ($q) {
                    $q->where('superagent_specification_approved', 1)
                      ->where('is_in_loading', 0)
                      ->where('superagent_loading_approved', 0);
                });
                break;

            case 'loading':
            case '1':
                $query->whereHas('bookingContainers', function ($q) {
                    $q->where('superagent_specification_approved', 1)
                      ->where('is_in_loading', 1)
                      ->where('superagent_loading_approved', 0);
                });
                break;

            case 'unloading':
            case 'discharge':
            case '2':
                $query->whereHas('bookingContainers', function ($q) {
                    $q->where('superagent_loading_approved', 1)
                      ->where('superagent_unloading_approved', 0);
                });
                break;

            case 'invoiced':
            case 'closed':
            case 'finished':
            case '3':
                $query->where(function ($sub) {
                    $sub->whereHas('invoice')
                        ->orWhereHas('bookingContainers', function ($qc) {
                            $qc->where('superagent_unloading_approved', 1);
                        });
                });
                break;
        }
    });
}

    public function scopeSortListing($query, $column = 'id', $direction = 'desc')
    {
        $allowed = [
            'id', 'name', 'email', 'address', 'phone', 'tax_no', 'bill_type', 'taxed',
            'private_company_id', 'attachments', 'password', 'session_id', 'created_at', 'updated_at',
            'invoice_number_auto_increment', 'wallet', 'opening_balance',
        ];
        $direction = is_string($direction) ? strtolower($direction) : null;
        if (!is_string($column) || !in_array($column, $allowed, true)
            || !in_array($direction, ['asc', 'desc'], true)) {
            $column = 'id';
            $direction = 'desc';
        }

        return $query->orderBy($column, $direction);
    }

